a4h/dsh_meal-base.body:
@EndUserText.label : 'Meal Table for Dictionary Search Helps'
@AbapCatalog.enhancement.category : #EXTENSIBLE_CHARACTER
@AbapCatalog.tableCategory : #TRANSPARENT
@AbapCatalog.deliveryClass : #A
@AbapCatalog.dataMaintenance : #ALLOWED
define table dsh_meal {

  key mandant    : mandt not null;
  key carrid     : s_carr_id not null;
  key mealnumber : s_mealnum not null;
  mealtype       : s_mealtype;
  include sdsh_s_honger with suffix hon;

}

a4h/dsh_s_meal_append.body:
@EndUserText.label : 'Dictionary Search Helps: Meal Append'
@AbapCatalog.enhancement.category : #NOT_CLASSIFIED
extend type dsh_meal with dsh_s_meal_append {

  dessert : s_dessert;

}

a4h/ddtest_stru_include-base.body:
@EndUserText.label : 'Structure with includes'
@AbapCatalog.enhancement.category : #EXTENSIBLE_ANY
define structure ddtest_stru_include {

  include ddtest_stru_char with suffix a;
  include ddtest_stru_char with suffix b;
  stru                : ddtest_stru_char;
  ref                 : reference to ddtest_stru_char;
  ref_boxed           : ddtest_stru_char boxed;
  ref_boxed_stru_ttyp : ddtest_stru_ttyp boxed;
  include ddtest_stru_char;
  include ddtest_view with suffix c;
  view                : ddtest_view;

}

a4h/test_sbd_append_add_vh.body:
@EndUserText.label : 'append value helps'
@AbapCatalog.enhancement.category : #NOT_EXTENSIBLE
extend type test_sbd_two_fields_class_intf with test_sbd_append_add_vh {

  extend class :
    with value help seo_classes_interfaces
      where language = 'EN'
        and name = test_sbd_two_fields_class_intf.class;
  extend interface :
    with value help seo_classes_interfaces
      where language = 'EN'
        and name = test_sbd_two_fields_class_intf.interface;

}

a4h/test_sbd_append_add_vah_and_fk.body:
@EndUserText.label : 'append foreign key and value help'
@AbapCatalog.enhancement.category : #NOT_EXTENSIBLE
extend type test_sbd_class_intf_wth_append with test_sbd_append_add_vah_and_fk {

  @AbapCatalog.foreignKey.label : 'extend class with foreign key'
  @AbapCatalog.foreignKey.keyType : #KEY
  @AbapCatalog.foreignKey.screenCheck : true
  extend class :
    with foreign key [1,1] seoclass
      where clsname = test_sbd_class_intf_wth_append.class
    with value help seo_classes_interfaces
      where language = 'EN'
        and name = test_sbd_class_intf_wth_append.class;
  @AbapCatalog.foreignKey.label : 'extend interface with foreign key'
  @AbapCatalog.foreignKey.keyType : #KEY
  @AbapCatalog.foreignKey.screenCheck : true
  extend interface :
    with foreign key [1,1] seoclass
      where clsname = test_sbd_class_intf_wth_append.interface
    with value help seo_classes_interfaces
      where language = 'EN'
        and name = test_sbd_class_intf_wth_append.interface;

}

